param([switch]$Baseline)
$ErrorActionPreference='Stop';$repo=[IO.Path]::GetFullPath("$PSScriptRoot/../..");$out="$repo/build-extractors/runtime-test/warswords-bonfire-retirement/$(Get-Date -Format yyyyMMdd-HHmmss-fff)";[void][IO.Directory]::CreateDirectory($out)
& "$PSScriptRoot/Invoke-WithRuntimeDiagnostics.ps1" -EvidenceDirectory "$out/evidence" -RuntimeDirectories @($out) -Test {
 $files=@("$repo/src/server/scripts/Scenario/Artifacts/Warrior/Warswords/Warswords.cpp","$repo/src/server/game/Spells/SpellEffects.cpp","$PSScriptRoot/WarswordsBonfireTest.cpp","$PSScriptRoot/prepare_bonfire_retirement.py","$PSScriptRoot/Test-WarswordsBonfireRetirement.ps1");$hashes=@{};foreach($p in $files){$hashes[$p]=(Get-FileHash -LiteralPath $p).Hash}
 $python='C:/Users/Admin/.cache/codex-runtimes/codex-primary-runtime/dependencies/python/python.exe';$mode=if($Baseline){'baseline'}else{'fixed'};& $python -X utf8 "$PSScriptRoot/prepare_bonfire_retirement.py" $out $mode;if($LASTEXITCODE){throw 'Bonfire scope/extraction failed'}
 $vs=& "${env:ProgramFiles(x86)}/Microsoft Visual Studio/Installer/vswhere.exe" -latest -products '*' -requires Microsoft.VisualStudio.Component.VC.Tools.x86.x64 -property installationPath
 $flags=if($Baseline){'/DBONFIRE_RETIREMENT_BASELINE'}else{''}
 [IO.File]::WriteAllText("$out/build.cmd","@echo off`r`ncall `"$vs/VC/Auxiliary/Build/vcvars64.bat`" >nul`r`ncl /nologo /EHsc /std:c++17 /W4 /MD /fsanitize=address /Zi $flags /I`"$out`" `"$PSScriptRoot/WarswordsBonfireTest.cpp`" /Fe`"$out/test.exe`" /Fo`"$out/test.obj`" /Fd`"$out/compiler.pdb`" /link /INCREMENTAL:NO`r`nexit /b %errorlevel%`r`n")
 & "$out/build.cmd" *> "$out/build.log";if($LASTEXITCODE){Get-Content "$out/build.log" -Tail 12;throw 'Bonfire ASAN compilation failed'}
 [IO.File]::WriteAllText("$out/run.cmd","@echo off`r`ncall `"$vs/VC/Auxiliary/Build/vcvars64.bat`" >nul`r`n`"$out/test.exe`"`r`nexit /b %errorlevel%`r`n")
 $info=[Diagnostics.ProcessStartInfo]::new();$info.FileName='cmd.exe';$info.Arguments='/d /c ""'+$out+'/run.cmd""';$info.UseShellExecute=$false;$info.CreateNoWindow=$true;$info.RedirectStandardOutput=$true;$info.RedirectStandardError=$true;$owned=[Diagnostics.Process]::new();$owned.StartInfo=$info;if(!$owned.Start()){throw 'Bonfire owned process launch failed'};$a=$owned.StandardOutput.ReadToEndAsync();$b=$owned.StandardError.ReadToEndAsync();$owned.WaitForExit();$exit=$owned.ExitCode;$stdout=$a.Result;$stderr=$b.Result;$owned.Dispose();[IO.File]::WriteAllText("$out/stdout.log",$stdout);[IO.File]::WriteAllText("$out/stderr.log",$stderr)
 @{exit=$exit;expected_counterfactual=[bool]$Baseline;stdout=(Get-FileHash "$out/stdout.log").Hash;stderr=(Get-FileHash "$out/stderr.log").Hash}|ConvertTo-Json|Set-Content "$out/process-result.json"
 if($Baseline){if($exit -ne 1 -or $stdout.Length -or $stderr.Trim() -cne 'completed bonfire remains selectable'){throw 'Pinned visible-interaction counterfactual differs'};'PASS expected-broken original bonfire: acknowledged criterion/step1 still leaves native flag selectable'}elseif($exit -or $stderr.Length -or $stdout -notmatch '^PASS 63 production bonfire/actual post-lock dispatch ASAN contexts:'){throw 'Bonfire retirement ASAN failed'}else{$stdout.Trim()}
 foreach($p in $files){if((Get-FileHash -LiteralPath $p).Hash -ne $hashes[$p]){throw 'Bonfire source changed during test'}};@{inputs=$hashes;baseline=[bool]$Baseline;asan=$true;complete_production_ai_and_native_dispatch=$true;exe=(Get-FileHash "$out/test.exe").Hash}|ConvertTo-Json -Depth 5|Set-Content "$out/inputs.json"
}
